def transform(grid):
    h, w = len(grid), len(grid[0])

    # The separator color forms complete rows and a complete column.
    separator = next(
        color for color in set(v for row in grid for v in row)
        if any(all(v == color for v in row) for row in grid)
        and any(all(grid[r][c] == color for r in range(h)) for c in range(w))
    )

    divider_rows = [r for r, row in enumerate(grid) if all(v == separator for v in row)]
    divider_cols = [
        c for c in range(w)
        if all(grid[r][c] == separator for r in range(h))
    ]

    def sections(length, dividers):
        result, start = [], 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < length:
            result.append((start, length))
        return result

    row_sections = sections(h, divider_rows)
    col_sections = sections(w, divider_cols)

    counts = {}
    for row in grid:
        for value in row:
            if value != separator:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    output = []
    for r0, r1 in row_sections:
        out_row = []
        for c0, c1 in col_sections:
            marks = sum(
                grid[r][c] != separator and grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            out_row.append(1 if marks >= 2 else background)
        output.append(out_row)
    return output
